#!/usr/bin/env python3
"""
open_handles.py
Opens a large number of dummy file handles (via /dev/null) and optionally
TCP sockets, to stress-test or demonstrate open-file-descriptor limits.

Usage:
    python3 open_handles.py [--count N] [--sockets] [--hold]

Options:
    --count N     Number of handles/sockets to open (default: 5000)
    --sockets     Open TCP sockets instead of file handles
    --hold        Keep handles open and wait for Ctrl+C (default: close immediately)
"""

import argparse
import socket
import sys
import time

def open_file_handles(count: int, hold: bool):
    handles = []
    failed = 0
    print(f"[*] Opening {count} file handles (/dev/null)...")
    for i in range(count):
        try:
            handles.append(open("/dev/null", "rb"))
        except OSError as e:
            failed += 1
            if failed == 1:
                print(f"    ✗ Failed at handle #{i}: {e}")
            break

    opened = len(handles)
    print(f"    ✓ Successfully opened : {opened}")
    if failed:
        print(f"    ✗ Failed             : {failed} (hit OS limit at #{opened})")

    if hold and handles:
        print("[*] Holding handles open — press Ctrl+C to release and exit.")
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            print("\n[*] Releasing handles...")

    for h in handles:
        h.close()
    print("[*] All handles closed.")


def open_sockets(count: int, hold: bool):
    sockets = []
    failed = 0
    print(f"[*] Opening {count} TCP sockets...")
    for i in range(count):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sockets.append(s)
        except OSError as e:
            failed += 1
            if failed == 1:
                print(f"    ✗ Failed at socket #{i}: {e}")
            break

    opened = len(sockets)
    print(f"    ✓ Successfully opened : {opened}")
    if failed:
        print(f"    ✗ Failed             : {failed} (hit OS limit at #{opened})")

    if hold and sockets:
        print("[*] Holding sockets open — press Ctrl+C to release and exit.")
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            print("\n[*] Releasing sockets...")

    for s in sockets:
        s.close()
    print("[*] All sockets closed.")


def main():
    parser = argparse.ArgumentParser(description="Open many file handles or sockets.")
    parser.add_argument("--count", type=int, default=5000,
                        help="Number of handles/sockets to open (default: 5000)")
    parser.add_argument("--sockets", action="store_true",
                        help="Open TCP sockets instead of file handles")
    parser.add_argument("--hold", action="store_true",
                        help="Keep handles open and wait for Ctrl+C")
    args = parser.parse_args()

    print(f"[*] Mode    : {'sockets' if args.sockets else 'file handles'}")
    print(f"[*] Count   : {args.count}")
    print(f"[*] Hold    : {args.hold}")
    print()

    if args.sockets:
        open_sockets(args.count, args.hold)
    else:
        open_file_handles(args.count, args.hold)


if __name__ == "__main__":
    main()
